/**
 * Response body for GET /v1/audit/receipts. Mirrors the post-MR-!72 shape produced by Recurse.Gateway.AuditPlane.ReceiptsHandler.render_response/4 (F002 + F004 + issue #44 facets fix). The receipts array contains the F001 split-envelope shape (signed_predicate + outer_container) per ReceiptSerializers.signed_predicate/2 and outer_container/2 (default opts — heavy bytes excluded; the SPA's Verify-Locally flow fetches them on demand). The cursor is opaque server-signed pagination state; null when no more pages. The optional facets object is present iff the request set ?facets=true and carries per-axis counts over the FULL filtered universe (not just the paginated page) per FR-012 + issue #44; SPA dashboard reads these into the left-rail picker.
 */
export interface AuditReceiptsListResponse {
  /**
   * Page of receipts in the F001 split-envelope shape.
   */
  receipts: {
    /**
     * Stable receipt identifier — UUID/ULID. Hoisted to the row's top level for SPA convenience; matches signed_predicate.run_id.
     */
    run_id: string;
    /**
     * DSSE-bound predicate fields per ReceiptSerializers.signed_predicate/2 default opts. tool_name + tool_summary are non-signed B7 row metadata; everything else is part of the signed bytes.
     */
    signed_predicate: {
      run_id: string;
      session_id: string | null;
      turn_id: string | null;
      /**
       * Atom-stringified canonical event kind (llm_call, tool_call, ui_query, ...).
       */
      event_kind: string | null;
      /**
       * JSON object with observed-JWT identity fields; backend stores as JSONB (:map). NOT a string — the pre-codegen hand-maintained TS type incorrectly typed this as string|null (issue #48 retiring F2).
       */
      machine_identity: {} | null;
      /**
       * JSON object with principal kind/subject/account_id; backend stores as JSONB (:map). NOT a string — hand-maintained TS type drift fixed in #48.
       */
      principal: {} | null;
      tenant_id: string | null;
      /**
       * Lowercase hex-encoded SHA-256.
       */
      policy_canonical_hash: string | null;
      /**
       * Lowercase hex-encoded SHA-256.
       */
      payload_hash: string | null;
      payload_uri: string | null;
      correlation_id: string | null;
      /**
       * Real KMS ARN OR observed:// synthetic marker per F13.
       */
      signer_kms_key_id: string | null;
      signer_key_version: string | null;
      timestamp: string | null;
      /**
       * B7 — non-signed UI metadata; populated for tool_call rows by the importer.
       */
      tool_name: string | null;
      /**
       * B7 — non-signed redacted 1-line tool summary; populated for tool_call rows.
       */
      tool_summary: string | null;
    };
    /**
     * Non-signed receipt container per ReceiptSerializers.outer_container/2 default opts.
     */
    outer_container: {
      verification_level: "signed" | "local_inclusion_verified" | "global_inclusion_verified" | null;
      tier_completeness_advisory: "partial" | "full" | null;
      session_chain_epoch: number | null;
      /**
       * Lowercase hex-encoded 32-byte session chain root.
       */
      session_chain_root: string | null;
      policy_decision: "allow" | "deny" | null;
      outcome: string | null;
      upstream_status_code: number | null;
      commit_retry_exhausted: boolean | null;
      /**
       * Tool-call extractor enriched tags (schema-on-read). Top-level keys are stable (`category`, `tool_kind`, `verb`, `argument_body`, `display_summary`, `scope_kind`, `scope_value`, `target_resources`, `semantic_args`); `semantic_args` is the per-category flex space (e.g. `{verb, subverb, writes, target_paths}` for Bash; `{server, tool, time_window_*, metric}` for MCP). NOT part of the signed predicate. NULL for non-tool_call rows AND for tool_call rows imported before the extractor pipeline existed. Extractor v2 (issue #62, 2026-04-30) promoted `tool_kind`/`verb`/`argument_body` to top-level so Cedar policies and dashboard facets can address them directly without descending into `semantic_args`.
       */
      tags: {
        /**
         * Coarse classification: `subprocess_exec`, `file_write`, `file_read`, `file_search`, `network_egress`, `mcp_tool_call`, `agent_dispatch`, `todo_management`, `notebook_edit`, `unknown`, `malformed`.
         */
        category?: string | null;
        /**
         * Coarse tool family for facets/Cedar attribute lookups: `bash`, `edit`, `read`, `search`, `webfetch`, `mcp`, `agent`, `todo`, `notebook_edit`, `unknown`. Stable across extractors.
         */
        tool_kind?: string | null;
        /**
         * Action verb. Bash → first command token (`echo`, `git`, `rm`); Edit/Write/MultiEdit/NotebookEdit → `patch`; Read → `cat`; Glob → `glob`; Grep → `grep`; WebFetch → `get`; WebSearch → `search`; MCP → tool name (e.g. `query_metrics`); Task/Agent → `dispatch`; TodoWrite → `todo`; unknown → null.
         */
        verb?: string | null;
        /**
         * Structured action subject. Bash → command minus the verb token; Edit/Write/MultiEdit/Read/NotebookEdit → file path; Glob/Grep → pattern; WebFetch → URL; WebSearch → query; MCP → JSON-encoded input args; Task/Agent → `subagent_type: <kind>`; TodoWrite → `<count> todos`; unknown → null.
         */
        argument_body?: string | null;
        display_summary?: string | null;
        scope_kind?: string | null;
        scope_value?: string | null;
        target_resources?: string[] | null;
        /**
         * Per-category flex space; key set varies. See `Recurse.Gateway.Extractors.ClaudeCodeJsonl` moduledoc for the per-category contract.
         */
        semantic_args?: {
          [k: string]: unknown | undefined;
        } | null;
        [k: string]: unknown | undefined;
      } | null;
    };
  }[];
  /**
   * Opaque server-signed cursor for the next page; null when no more pages.
   */
  cursor: string | null;
  /**
   * Per-axis counts over the FULL filtered universe (not just this page). Present iff the request set ?facets=true. Each axis is a string→count map; kinds with zero rows are ABSENT from the map (the SPA fills the canonical enum at count 0). Issue #44 (2026-04-30).
   */
  facets?: {
    event_kind: {
      [k: string]: number | undefined;
    };
    policy_decision: {
      [k: string]: number | undefined;
    };
    verification_level: {
      [k: string]: number | undefined;
    };
  };
}

/**
 * Response body for GET /v1/auth/me — current authenticated session principal info derived from the BrowserSessionPlug-lifted session. Does NOT expose the JWT or any cookie content. Per contracts/audit_api_extensions.md §'Auth introspection' the shape is flat snake_case (the SPA's useAuth hook reads each field directly).
 */
export interface AuthMe {
  /**
   * Stable principal identifier (e.g., 'alice@corp', 'auth0|...'), straight from the JWT 'sub' / principal.subject claim.
   */
  principal_subject: string;
  /**
   * Console role the principal carries for this session. Single role per session in F004.
   */
  recurse_role: "tenant_auditor" | "platform_operator";
  /**
   * ULID identifying the tenant that owns this Browser Session. Single-tenant per deployment in F004.
   */
  tenant_id: string;
  /**
   * ULID identifying this specific Browser Session (cookie envelope). Stable across the cookie's 8h absolute lifetime; rotates on a fresh login.
   */
  browser_session_id: string;
  /**
   * RFC 3339 UTC instant when the cookie envelope hits its 8h absolute timeout. After this, BrowserSessionPlug drops the cookie regardless of activity.
   */
  session_expires_at: string;
  /**
   * RFC 3339 UTC instant when the cookie envelope hits its 60-min idle timeout, computed from last_activity_at. Refreshed by mutation-only rotation.
   */
  session_idle_timeout_at: string;
}

