/**
 * Metadata contract for the synchronous response of POST /v1/audit/export (F002 T061 / FR-022). The HTTP response body itself is binary (application/zip) — for N=1 a single inner zip; for N>1 a zip-of-zips with one inner zip per run_id, both shapes emitted by Recurse.Gateway.AuditPlane.ExportHandler.do_handle/3 via EvidenceZipBuilder.build/2 + build_many/2. JSON Schema cannot describe binary body bytes, so this schema documents the structured ENVELOPE the SPA's downloader (ExportEvidenceButton.downloadEvidence) materializes: the blob, the parsed Content-Disposition filename, the response status, and the response Content-Type. The SPA's hand-maintained shape pre-#48 was untyped; this gives a single typed surface every consumer (single-receipt CTA + future BulkActionBar) imports. Error responses go through error_envelope.json (the F001 envelope), not this shape.
 */
export interface ExportResponse {
  /**
   * Filename parsed from the Content-Disposition header per RFC 6266; backend emits `evidence-<basic-iso8601>.zip`. Falls back client-side to a synthetic timestamped name when the header is missing.
   */
  filename: string;
  /**
   * Always application/zip; the backend sets this via Plug.Conn.put_resp_content_type/2 in ExportHandler.do_handle/3.
   */
  content_type: "application/zip";
  /**
   * Size in bytes of the downloaded zip blob. Used by the SPA's UI for download progress + audit-log of the size delivered.
   */
  byte_size: number;
  /**
   * Echo of the request's run_ids; populated by the SPA from the originating request shape (the response body itself is binary so this is not a wire field). Optional — the SPA carries it through for UI book-keeping.
   *
   * @minItems 1
   * @maxItems 100
   */
  run_ids?: [string, ...string[]];
}

