/**
 * Single MCP server entry in the Recurse Trusted Registry. Vertical-slice scaffold for the demo (Path B); Phase-2+ adds digital-signing chain for SBOM components and per-tenant overrides. Self-contained: shape mirrors `mcp_registry_list_response.json#/$defs/McpRegistryEntry` so the codegen path stays single-file.
 */
export interface McpRegistryEntry {
  /**
   * Stable kebab-case identifier; URL-safe.
   */
  id: string;
  name: string;
  description: string;
  /**
   * Source URL or identifier (e.g. github.com/<org>/<repo>).
   */
  source: string;
  version: string;
  transport: "http" | "stdio" | "websocket" | "sse";
  trust_tier: "verified" | "community" | "quarantined";
  publisher: string;
  capabilities: {
    tools: {
      name: string;
      description: string;
      input_schema_ref?: string;
    }[];
  };
  policy_constraints: {
    /**
     * Cedar policy strings gating tool calls against this MCP server.
     */
    cedar_policies?: string[];
    /**
     * Hard cap; 0 means policy-denied (used for quarantined entries).
     */
    rate_limit_per_minute?: number;
  };
  sbom: {
    format: string;
    /**
     * SBOM content digest (sha256:<hex>) — Phase-1 placeholder; Phase-2+ becomes mandatory and verified.
     */
    digest: string;
    components: {
      name: string;
      version: string;
      license?: string;
      purl?: string;
      vulnerabilities?: {
        id: string;
        source?: string;
        severity: "low" | "medium" | "high" | "critical" | "unknown";
        summary: string;
        /**
         * Optional advisory URL (NVD, GHSA, vendor security bulletin).
         */
        url?: string;
        fixed_versions?: string[];
      }[];
    }[];
  };
}

