/**
 * Request body for PATCH /v1/mcp/registry/{id} — the F7 quarantine workflow. Operator-only mutation that flips an entry's trust_tier (and the documented Cedar policy clause + rate_limit_per_minute). Emits a DSSE-signed :ui_mcp_quarantine ledger receipt BEFORE the HTTP response (Principle III).
 */
export interface McpRegistryQuarantineRequest {
  /**
   * Target trust tier. Quarantining (verified|community -> quarantined) snapshots the prior cedar_policies + rate_limit_per_minute into sibling fields and rewrites cedar_policies to a forbid(...) clause + rate_limit_per_minute=0. Restoring (quarantined -> verified|community) reads back the snapshot fields when present.
   */
  trust_tier: "verified" | "community" | "quarantined";
  /**
   * Optional auditor-facing free-text justification (≤ 500 bytes). Carried into the receipt payload for SIEM correlation. Empty string normalises to null.
   */
  reason?: string | null;
}

/**
 * Request body for POST /v1/mcp/{server}/tools/{tool}. Loosely follows the JSON-RPC 2.0 tools/call shape from the MCP HTTP transport spec; the demo subset accepts an `arguments` map plus optional `id` for client correlation.
 */
export interface McpToolCallRequest {
  /**
   * Client-supplied correlation id; echoed back on the response.
   */
  id?: string | number | null;
  /**
   * Tool-specific arguments. Validated per tool inside the handler (the per-tool schemas live under capabilities[].input_schema_ref in the registry entry).
   */
  arguments?: {
    [k: string]: unknown | undefined;
  };
}

/**
 * Response envelope for POST /v1/mcp/{server}/tools/{tool}. Carries the tool result alongside Recurse-specific provenance metadata: the run_id of the emitted attestation receipt and the policy decision that gated the call.
 */
export interface McpToolCallResponse {
  id?: string | number | null;
  server: string;
  tool: string;
  policy_decision: "allow" | "deny";
  /**
   * Human-readable cause when policy_decision == "deny". Null on allow.
   */
  deny_reason?: string | null;
  /**
   * Trust tier of the registry entry at call time. Quarantined ⇒ deny.
   */
  trust_tier?: "verified" | "community" | "quarantined";
  /**
   * run_id of the :mcp_tool_call attestation emitted for this call. Auditors deep-link from this value into the Audit Console.
   */
  attested_run_id: string;
  /**
   * Tool-specific result payload. Shape varies by tool. Null when policy_decision == "deny".
   */
  result:
    | {
        [k: string]: unknown | undefined;
      }
    | unknown[]
    | string
    | number
    | boolean
    | null;
}

/**
 * Response body for GET /v1/audit/parser-drift (spec 012 S4). One row per (api_format, event_type) an LLM-proxy parser reported as unrecognised for the session's tenant, most recently seen first. `sample_redacted` is keys-only (`keys=a,b,c`), never payload content. `new_since_boot` is the number of rows first inserted since this gateway node booted (the same counter /readyz reports as `parser_drift`).
 */
export interface ParserDriftListResponse {
  events: {
    id: number;
    /**
     * LlmProviderConfig.api_format the parser was selected for (e.g. anthropic_messages, openai_responses).
     */
    api_format: string;
    /**
     * Discriminator the parser logged: `event:<type>`, `block:<type>`, `delta:<type>` (Anthropic) or `event:<type>`, `output_item:<type>` (OpenAI Responses).
     */
    event_type: string;
    /**
     * Keys-only sample of the first sighting (`keys=a,b,c`, at most 200 bytes).
     */
    sample_redacted: string | null;
    first_seen: string;
    last_seen: string;
    count: number;
  }[];
  new_since_boot: number;
}

/**
 * 422 error variant returned by GET /v1/audit/payload?run_id=... when the targeted receipt is predicate-only-by-design (signed_predicate IS the audit content; no separate payload bytes were stored). Common case: receipts emitted by the JSONL session importer (MR !80) whose payload_uri uses the recurse://import/ scheme. Distinguished from 404 (resource missing) and 400 (request malformed) — the request was understood and the receipt exists; the resource just cannot be served because there are no detached bytes by design. The shape is a constrained subset of error_envelope.json with `error` pinned to `ERR_PREDICATE_ONLY`; the predicate-only payload_uri is echoed in `error_description` so SIEM forwarders + auditor diagnostics can confirm provenance without a second roundtrip. Built by Recurse.Gateway.AuditPlane.ErrorEnvelope.send_unprocessable_entity/4 from PayloadBroker.handle/1's predicate_only_imported branch (issue #60).
 */
export interface PayloadErrorPredicateOnly {
  /**
   * Pinned to ERR_PREDICATE_ONLY for this variant.
   */
  error: "ERR_PREDICATE_ONLY";
  /**
   * Human-readable explanation. Includes the predicate-only payload_uri (recurse://import/...) so the auditor can confirm provenance.
   */
  error_description: string;
  /**
   * Request correlation ID; defaults to 'unknown' when absent.
   */
  correlation_id: string;
  /**
   * Always null for this variant (no denial receipt is emitted; the response is by-design 422, not a Cedar deny).
   */
  attested_run_id?: string | null;
}

