/**
 * Response body for POST /v1/audit/receipts/{run_id}/verify (FR-018). Mirrors Recurse.Gateway.Admin.LocalVerifyHandler.run_checks_and_respond/3 + check_to_json/1. Carries the 5-step cryptographic verification result the SPA renders as five rows in the Verify Locally tab. Each check name + step number is fixed by the FR-018 contract; status atom is pass|fail; explanation is human-readable text the SPA renders verbatim under the row.
 */
export interface VerifyResponse {
  /**
   * Receipt being verified — matches the {run_id} path parameter.
   */
  run_id: string;
  /**
   * Aggregate boolean: pass iff every check in `checks` passed; fail otherwise. Stringified atom from the backend.
   */
  overall_status: "pass" | "fail";
  /**
   * Five-step verification result; ordered by step (1..5).
   */
  checks: {
    /**
     * 1-indexed step number — matches LocalVerifyHandler.check/4.
     */
    step: number;
    /**
     * Backend check identifier; SPA maps to the row testId + label via CHECK_ORDER.
     */
    name:
      | "signature"
      | "local_merkle_inclusion"
      | "global_merkle_inclusion"
      | "policy_hash_match"
      | "payload_hash_match";
    status: "pass" | "fail";
    /**
     * Backend-emitted human-readable explanation. The SPA renders this verbatim; auditors must be able to reproduce the result without server access (e.g., expected/actual hex hashes on mismatch, algorithm + key id on success).
     */
    explanation: string;
  }[];
  /**
   * ISO-8601 UTC timestamp when the server completed the checks.
   */
  verified_at: string;
  /**
   * Tier-completeness advisory copied from the receipt; nullable. Discovery-tier Standalone is always partial.
   */
  tier_completeness_advisory: "partial" | "full" | null;
}
